using System.Windows;using System.Windows.Controls;using DirectorFamilyTravelDesk.Models;
namespace DirectorFamilyTravelDesk.Views; public partial class TripsView:UserControl,IRefreshable{private List<TripListItem> _all=new();public TripsView(){InitializeComponent();}public void RefreshData(){_all=App.Repository.GetTrips();StatusFilter.Items.Clear();StatusFilter.Items.Add("All Statuses");foreach(var s in App.Repository.GetLookup("status_options"))StatusFilter.Items.Add(s.Name);StatusFilter.SelectedIndex=0;Apply();}private void Apply(){var q=_all.AsEnumerable();var s=SearchBox?.Text?.Trim();if(!string.IsNullOrWhiteSpace(s))q=q.Where(x=>string.Join(' ',x.TripCode,x.RouteLabel,x.Travellers,x.OnwardPnr,x.ReturnPnr,x.Status).Contains(s,StringComparison.OrdinalIgnoreCase));var st=StatusFilter?.SelectedItem?.ToString();if(!string.IsNullOrWhiteSpace(st)&&st!="All Statuses")q=q.Where(x=>x.Status==st);GridTrips.ItemsSource=q.ToList();}private void Filter_Changed(object s,EventArgs e){if(IsLoaded)Apply();}private void New_Click(object s,RoutedEventArgs e){var w=new TripEditorWindow{Owner=Window.GetWindow(this)};if(w.ShowDialog()==true)RefreshData();}private void Edit_Click(object s,RoutedEventArgs e){if(GridTrips.SelectedItem is not TripListItem x)return;var w=new TripEditorWindow(x.Id){Owner=Window.GetWindow(this)};if(w.ShowDialog()==true)RefreshData();}private void Delete_Click(object s,RoutedEventArgs e){if(GridTrips.SelectedItem is not TripListItem x)return;if(MessageBox.Show($"Delete {x.TripCode}?","Confirm",MessageBoxButton.YesNo,MessageBoxImage.Warning)==MessageBoxResult.Yes){App.Repository.DeleteTrip(x.Id);RefreshData();}}}